        ('11021111-0000-4000-8000-000000000001', 'Which concentration term is independent of temperature?', '{"A":"Molarity (M)","B":"Molality (m) and Mole fraction (x)","C":"Normality (N)","D":"Mass by volume %"}'::jsonb, 'B', 'MCQ', 'Chemistry', 'Some Basic Concepts of Chemistry', 1, 'Molality and mole fraction depend solely on mass, not temperature-sensitive volume.', NULL, NULL, 'Molality and mole fraction depend solely on mass, not temperature-sensitive volume.', 'EASY', true),
        ('11021111-0000-4000-8000-000000000002', 'Number of molecules present in 1.8 g of H₂O (molar mass 18 g/mol) is:', '{"A":"6.022 × 10²³","B":"6.022 × 10²²","C":"3.011 × 10²³","D":"1.204 × 10²⁴"}'::jsonb, 'B', 'MCQ', 'Chemistry', 'Some Basic Concepts of Chemistry', 1, '0.1 mol × 6.022×10²³ = 6.022×10²² molecules.', NULL, NULL, '0.1 mol × 6.022×10²³ = 6.022×10²² molecules.', 'EASY', true),
        ('11021111-0000-4000-8000-000000000003', 'What is the empirical formula of glucose (C₆H₁₂O₆)?', '{"A":"C₂H₄O₂","B":"CH₂O","C":"C₃H₆O₃","D":"CHO"}'::jsonb, 'B', 'MCQ', 'Chemistry', 'Some Basic Concepts of Chemistry', 1, 'Dividing subscripts 6:12:6 by 6 gives CH₂O.', NULL, NULL, 'Dividing subscripts 6:12:6 by 6 gives CH₂O.', 'EASY', true),
        ('11021111-0000-4000-8000-000000000004', 'In 3A + 2B -> C, 4 mol of A reacts with 4 mol of B. The limiting reagent is:', '{"A":"A","B":"B","C":"C","D":"None"}'::jsonb, 'A', 'MCQ', 'Chemistry', 'Some Basic Concepts of Chemistry', 1, '4 mol A needs (2/3)×4 = 2.67 mol B (< 4 mol available), so A finishes first.', NULL, NULL, '4 mol A needs (2/3)×4 = 2.67 mol B (< 4 mol available), so A finishes first.', 'EASY', true),
        ('11021111-0000-4000-8000-000000000005', 'According to Gay-Lussac''s Law of Gaseous Volumes, H₂ and Cl₂ combine to form HCl in volume ratio:', '{"A":"1 : 1 : 1","B":"1 : 1 : 2","C":"2 : 1 : 2","D":"1 : 2 : 1"}'::jsonb, 'B', 'MCQ', 'Chemistry', 'Some Basic Concepts of Chemistry', 1, 'H₂(g) + Cl₂(g) -> 2HCl(g) => 1 : 1 : 2.', NULL, NULL, 'H₂(g) + Cl₂(g) -> 2HCl(g) => 1 : 1 : 2.', 'EASY', true),
        ('11021111-0000-4000-8000-000000000006', 'Assertion (A): 18 mL of pure liquid water at 4°C contains 1 mole of water molecules.
